class ModalDialog {
    constructor(dialogId, triggerSelector, closeSelector, confirmSelector, cancelSelector) {
        this.dialog = document.getElementById(dialogId);
        this.triggers = document.querySelectorAll(triggerSelector);
        this.closeBtn = this.dialog.querySelector(closeSelector);
        this.confirmBtn = this.dialog.querySelector(confirmSelector);
        this.cancelBtn = this.dialog.querySelector(cancelSelector);
        this.overlay = this.dialog.querySelector('.dialog-overlay');

        this.previousActiveElement = null;
        this.currentImageId = null;
        this.currentImageName = null;

        this.init();
    }

    init() {
        // Open dialog on trigger click
        this.triggers.forEach(trigger => {
            trigger.addEventListener('click', (e) => this.handleTriggerClick(e));
        });

        // Close dialog
        this.closeBtn.addEventListener('click', () => this.close());
        this.cancelBtn.addEventListener('click', () => this.close());
        this.overlay.addEventListener('click', () => this.close());

        // Confirm deletion
        this.confirmBtn.addEventListener('click', () => this.handleConfirm());

        // Keyboard support
        this.dialog.addEventListener('keydown', (e) => this.handleKeyDown(e));
    }

    handleTriggerClick(e) {
        e.preventDefault();
        const trigger = e.currentTarget;

        // Get image metadata from trigger element
        this.currentImageId = trigger.getAttribute('data-image');
        this.currentImageName = trigger.getAttribute('aria-label')?.replace('Delete ', '').replace(' image', '') || 'this image';

        // Update dialog content
        document.getElementById('imageName').textContent = this.currentImageName;

        // Open dialog
        this.open(trigger);
    }

    open(triggerElement) {
        // Store the element that triggered the dialog for focus restoration
        this.previousActiveElement = triggerElement;

        // Show dialog
        this.dialog.removeAttribute('hidden');

        // Focus the confirm button (primary action is dangerous, so focus cancel first for safety)
        this.focusFirstElement();

        // Prevent body scroll
        document.body.style.overflow = 'hidden';
    }

    close() {
        // Hide dialog
        this.dialog.setAttribute('hidden', '');

        // Restore body scroll
        document.body.style.overflow = '';

        // Restore focus to trigger element
        if (this.previousActiveElement) {
            this.previousActiveElement.focus();
        }

        // Clear state
        this.currentImageId = null;
        this.currentImageName = null;
    }

    focusFirstElement() {
        // For safety, focus the cancel button instead of the dangerous confirm button
        this.cancelBtn.focus();
    }

    handleConfirm() {
        // Simulate deletion (in real app, this would call an API)
        console.log(`Deleting image: ${this.currentImageId}`);

        // Find and remove the card from the gallery
        const trigger = document.querySelector(`[data-image="${this.currentImageId}"]`);
        if (trigger) {
            const card = trigger.closest('.image-card');
            if (card) {
                // Add fade-out animation
                card.style.animation = 'fadeOut 300ms ease-out forwards';
                setTimeout(() => {
                    card.remove();
                    this.close();
                }, 300);
            }
        }
    }

    handleKeyDown(e) {
        // Close on Escape
        if (e.key === 'Escape') {
            e.preventDefault();
            this.close();
        }

        // Trap focus within dialog
        if (e.key === 'Tab') {
            this.handleTabKey(e);
        }
    }

    handleTabKey(e) {
        // Get all focusable elements in the dialog
        const focusableElements = this.dialog.querySelectorAll(
            'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );

        if (focusableElements.length === 0) return;

        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];
        const activeElement = document.activeElement;

        if (e.shiftKey) {
            // Shift + Tab
            if (activeElement === firstElement) {
                e.preventDefault();
                lastElement.focus();
            }
        } else {
            // Tab
            if (activeElement === lastElement) {
                e.preventDefault();
                firstElement.focus();
            }
        }
    }
}

// Add fade-out animation
const style = document.createElement('style');
