+        // Find and remove the card from the gallery
+        const trigger = document.querySelector(`[data-image="${this.currentImageId}"]`);
+        if (trigger) {
+            const card = trigger.closest('.image-card');
+            if (card) {
+                // Add fade-out animation
+                card.style.animation = 'fadeOut 300ms ease-out forwards';
+                setTimeout(() => {
